using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class IsaacAsimov
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It is change, continuing change, inevitable change, that is the dominant factor in society today. No sensible decision can be made any longer without taking into account not only the world as it is, but the world as it will be.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There is no belief, however foolish, that will not gather its faithful adherents who will defend it to the death.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "You wait for the war to happen like vultures. If you want to help, prevent the war.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Outside intelligences, exploring the Solar System with true impartiality, would be quite likely to enter the Sun in their records thus: Star X, spectral class G0, 4 planets plus debris.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Science fiction writers foresee the inevitable, and although problems and catastrophes may be inevitable, solutions are not.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There are limits beyond which your folly will not carry you. I am glad of that. In fact, I am relieved.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "If I were not an atheist, I would believe in a God who would choose to save people on the basis of the totality of their lives and not the pattern of their words.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I feel that the longest and worst punishment should be reserved for those who slandered God by inventing Hell.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "The saddest aspect of life right now is that science gathers knowledge faster than society gathers wisdom.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It is only afterward that a new idea seems reasonable. To begin with, it usually seems unreasonable.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "The dullness of fact is the mother of fiction.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Predicting the future is a hopeless, thankless task, with ridicule to begin with and, all too often, scorn to end with.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "History is a story without an end.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Private profit is often hidden under a careful coating of great patriotism.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Start with a planet like the earth, with a complement of simple compounds bound to exist upon it, add the energy of a nearby sun, and you are bound to end with nucleic acids. You can't avoid it.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It is important to remember that the viciousness and wrongs of life stick out very plainly but that even at the worst times there is a great deal of goodness, kindness, and day-to-day decency that goes unnoticed and makes no headlines.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There is a kind of selective memory that afflicts men when they view the past. They see the good and overlook the evil.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Often, writers on historical events tend to consider ... a loss of willingness to fight as a sign of \"decadence,\" as though there were something despicable about not being a bully and not being willing to engage in mass murder. Perhaps we ought to feel instead that to cease to be warlike means to begin to be civilized and decent.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "In the world of today can there be peace anywhere until there is peace everywhere?", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "[N]o matter how outrageous a lie may be, it will be accepted if stated loudly enough and often enough.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It is by the Imperial Capital that contemporaries (and posterity, too) judge an Empire, and its magnificence impresses them mightily and leads them to judge the Emperor a great man and hero, even though it may all be based on robbery, and though the provinces of the Empire may be sunk in misery.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Probably, the most-often-repeated lesson in history is that foreigners who are called in to help one side in a civil war take over for themselves. It is a lesson that seems never to be learned despite endless repetition.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There has never been any custom, however useless it may become with changing conditions, that isn't clung to desperately simply because it is something old and familiar.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It is all too easy to forget that there are emotional motivations in history, as well as economic ones.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It seemed to him Euphemius it would be a brilliant notion to call in an outside force to fight on his behalf. This same brilliant notion has occurred to participants in civil wars uncounted times in history and it has ended in catastrophe just about every time, since those called in invariably take over for themselves. Of all history's lessons, this seems to be the plainest, and the most frequently ignored.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Had Hannibal had a government behind him that knew how to exploit victories – had he been born a Roman, for instance – he might have conquered the world.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I consider one of the most important duties of any scientist the teaching of science to students and to the general public.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Inspect every piece of pseudoscience and you will find a security blanket, a thumb to suck, a skirt to hold. What does the scientist have to offer in exchange? Uncertainty! Insecurity!", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "For man to become successful, for man to establish himself as the ruler of the planet, it was necessary for him to use his brain as something more than a device to make the daily routine of getting food and evading enemies a little more efficient. Man had to learn to control his environment.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Can the word ‘best’ mean anything at all, except to some particular person in some particular mood?", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Hypocrisy is a universal phenomenon. It ends with death, but not before.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Science is a systematic method for studying and working out those generalizations that seem to describe the behavior of the universe. It could exist as a purely intellectual game that would never affect the practical life of human beings either for good or evil, and that was very nearly the case in ancient Greece, for instance. Technology is the application of scientific findings to the tools of everyday life, and that application can be wise or unwise, useful or harmful. Very often, those who govern technological decisions are not scientists and know little about science.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There is no belief, however foolish, that will not gather its faithful adherents who will defend it to the death.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "If, as I maintain and firmly believe, there is no objective definition of intelligence, and what we call intelligence is only a creation of cultural fashion and subjective prejudice, what the devil is it we test when we make use of an intelligence test?", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Science fiction writers foresee the inevitable, and although problems and catastrophes may be inevitable, solutions are not.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Self-education is, I firmly believe, the only kind of education there is.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Straightforward preaching spoils the effectiveness of a story. If you can't resist the impulse to improve your fellow human beings, do it subtly.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There is no way of being almost funny or mildly funny or fairly funny or tolerably funny. You are either funny or not funny and there is nothing in between. And usually it is the writer who thinks he is funny and the reader who thinks he isn't.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "[S]cientific writing is abhorrently stylized and places a premium on poor quality.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "If you're going to write a story, avoid contemporary references. They date a story and they have no staying power.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Generals are, as a matter of course, allowed to be far more idiotic than ordinary human beings are permitted to be.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "People are entirely too disbelieving of coincidence. They are far too ready to dismiss it and to build arcane structures of extremely rickety substance in order to avoid it. I, on the other hand, see coincidence everywhere as an inevitable consequence of the laws of probability, according to which having no unusual coincidence is far more unusual than any coincidence could possibly be.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "The history of science is full of revolutionary advances that required small insights that anyone might have had, but that, in fact, only one person did.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "We cannot afford enemies any more... Within a generation or two human society will be in total destructive disarray. Heaven knows how bad it will be. The most optimistic view I can take is this: Things will get so bad within a dozen years that it will become obvious ... that we must, whether were like each other or not, work together. We have no choice in the matter. ... Technologically, we can stop overpopulation, but we have to persuade people to accept the technology. ... Babies are the enemies of the human race ... Let's consider it this way: by the time the world doubles its population, the amount of energy we will be using will be increased sevenfold which means probably the amount of pollution that we are producing will also be increased sevenfold. If we are now threatened by pollution at the present rate, how will we be threatened with sevenfold pollution by, say, 2010 A.D., distributed among twice the population? We'll be having to grow twice the food out of soil that is being poisoned at seven times the rate.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I believe that only scientists can understand the universe. It is not so much that I have confidence in scientists being right, but that I have so much in nonscientists being wrong.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Individual science fiction stories may seem as trivial as ever to the blinder critics and philosophers of today — but the core of science fiction, its essence, the concept around which it revolves, has become crucial to our salvation if we are to be saved at all.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Where any answer is possible, all answers are meaningless.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I wouldn't give an astrologer the time of day.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It is surely better to be wronged than to do wrong.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "The purpose of aphorisms is to keep fools who have memorised them from having nothing to say.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There is less trouble and trauma involved in writing a new piece than in trying to salvage an unsatisfactory old one.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "The undramatic fact is that I just think and think and think until I have something for a story, and there is nothing marvelous or artistic about the phenomenon.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Certain success evicts one from the paradise of winning against the odds.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "The military mind remains unparalleled as a vehicle of creative stupidity.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It is very likely that there are many, many planets carrying life, even intelligent life, throughout the universe, because there are so many stars. By sheer chance, even if those chances are small, a great many life forms and a great many intelligences may exist.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There is a cult of ignorance in the United States, and there always has been. The strain of anti-intellectualism has been a constant thread winding its way through our political and cultural life, nurtured by the false notion that democracy means that \"my ignorance is just as good as your knowledge.\"", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "We can 'all' be members of the intellectual elite and then, and only then, will a phrase like \"America's right to know\" and, indeed, any true concept of democracy, have any meaning.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "[Creationists] make it sound as though a \"theory\" is something you dreamt up after being drunk all night.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "When you write a short story ... you had better know the ending first. The end of a story is only the end to the reader. To the writer, it's the beginning. If you don't know exactly where you're going every minute you're writing, you'll never get there — or anywhere.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Necessity makes a joke of civilization.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I make no secret about being Jewish ... I just think it's more important to be human and to have a human heritage; and I think it is wrong for anyone to feel that there is anything special about any one heritage of whatever kind. It is delightful to have the human heritage exist in a thousand varieties, for it makes for greater interest, but as soon as one variety is thought to be more important than another, the groundwork is laid for destroying them all.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I am not a visual person. I have spent so many bounded years in my childhood that I have grown used to having books as my window on reality.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Writing is hard work. The fact that I love doing it doesn't make it less hard work. People who love tennis will sweat themselves to exhaustion playing it, and the love of the game doesn't stop the sweating. The casual assumption that writers are unemployed bums because they don't go to the office and don't have a boss is something every writer has to live with. I have never known a writer who hasn't suffered as a result of this, hasn't resented it, and hasn't dreamed of murdering the next person who says \"Boy, you've sure got it made. You just sit there and toss off a story or something whenever you feel like it.\"", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "The fact is that I've never called myself a genius, and I think the term has been cheapened by overuse into meaninglessness. If other people want to call me that, that's their problem.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I joke sometimes to the effect that when I approach a part of a book where I must explain something I don't understand, I just type faster and faster and faster. Then, when I get to the part I don't understand, sheer inertia pushes me through. That's not literally true, of course, but there's something to it psychologically.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "No matter how various the subject matter I write on, I was a science-fiction writer first and it is as a science-fiction writer that I want to be identified.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "The best way to describe anyone is to give an example of the kind of thing he would do.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There are many aspects of the universe that still cannot be explained satisfactorily by science; but ignorance only implies ignorance that may someday be conquered. To surrender to ignorance and call it God has always been premature, and it remains premature today.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There is no version of primeval history, preceding the discoveries of modern science, that is as rational and as inspiring as that of the first eleven chapters of the Book of Genesis.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "If one thing goes without saying, almost anything can.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "And it is these ignorant people, the most uneducated, the most unimaginative, the most unthinking among us, who would make themselves the guides and leaders of us all; who would force their feeble and childish beliefs on us; who would invade our schools and libraries and homes in order to tell us what books to read and what not, what thoughts to think and what not, what conclusions to accept and what not. And what does the Bible say? \"If the blind lead the blind, both shall fall into the ditch\" (Matthew 15:14).", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "But suppose we 'were' to teach creationism. What would be the content of the teaching? Merely that a creator formed the universe and all species of life ready-made? Nothing more? No details?", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I am an atheist, out and out. It took me a long time to say it. I've been an atheist for years and years, but somehow I felt it was intellectually unrespectable to say one was an atheist, because it assumed knowledge that one didn't have. Somehow, it was better to say one was a humanist or an agnostic. I finally decided that I'm a creature of emotion as well as of reason. Emotionally, I am an atheist. I don't have the evidence to prove that God doesn't exist, but I so strongly suspect he doesn't that I don't want to waste my time.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "An optimistic view of the future would indicate that before long, the clear necessity of expanding humanity's horizons would cause ... space settlements to be built. The construction would also serve as a great project that not only would be clearly of great benefit, but might induce human cooperation in something large enough to fire the heart and mind, and make people forget the petty quarrels that have engaged them for thousands of years in wars over insignificant scraps of earthly territory.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It is a rather sad commentary on humanity that it is always so attractive to think that some small group \"controls the Earth\"—the Jews, the international bankers, the Communists, the Masons, the Trilateral Commission. Those who believe such things are so sincere, so harried, so paranoid and, if the times are bad enough, and if the hunger for a scapegoat is great enough—so convincing. The Nazis are the most dreadful example in recent history of how far madmen can go when riding the skeletal horse of paranoia, but their example has by no means cured the world.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Are there things about the universe that we cannot know in the usual way of observing and measuring, but that we can know in some other way—intuition, revelation, mad insight? If so, how can you know that what you know in these non-knowing ways is really so. Anything you know without knowing, others can know only on your flat statement without any proof other than “I know!”", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I get a certain pleasure in knowing that I live not merely in a city but in Manhattan, the center of New York City, a region so unique in many ways that I honestly believe that Earth is divided into halves: Manhattan and non-Manhattan.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Miniaturization doesn't actually make sense unless you miniaturize the very atoms of which matter is composed. Otherwise a tiny brain in a man the size of an insect, composed of normal atoms, is composed of too few atoms for the miniaturized man to be any more intelligent than the ant. Also, miniaturizing atoms is impossible according to the rules of quantum mechanics.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Titles are an important part of a story and I take considerable care in choosing one. In fact, I cannot start a story until I have chosen a title.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Once you've dissected a joke, you're about where you are when you've dissected a frog. It's dead.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "In my fiction I am careful to make everything probable and to tie up all loose ends. Real life is not hampered by such considerations.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There is more to a science fiction story than the science it contains. There is also the 'story'.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "There are limits beyond which your folly will not carry you. I am glad of that. In fact, I am relieved.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "All life is nucleic acid; the rest is commentary", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Good literature, all if it, is supposed to illuminate the human condition.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Of all the cultural aspects of humanity, the only one which is not broken up into national or regional splinters is science. Different nations have different languages, they may have different religions, may have different dietaries, may have different holidays, different ways of thinking, but here’s only one science.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "It's going to destroy it all. I use what I call my bathroom metaphor. If two people live in an apartment, and there are two bathrooms, then both have what I call freedom of the bathroom, go to the bathroom any time you want, and stay as long as you want to for whatever you need. And this to my way is ideal. And everyone believes in the freedom of the bathroom. It should be right there in the Constitution. But if you have 20 people in the apartment and two bathrooms, no matter how much every person believes in freedom of the bathroom, there is no such thing. You have to set up, you have to set up times for each person, you have to bang at the door, aren't you through yet, and so on. And in the same way, democracy cannot survive overpopulation. Human dignity cannot survive it. Convenience and decency cannot survive it. As you put more and more people onto the world, the value of life not only declines, but it disappears. It doesn't matter if someone dies.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Science doesn't purvey absolute truth. Science is a mechanism. It's a way of trying to improve your knowledge of nature. It's a system for testing your thoughts against the universe and seeing whether they match. And this works, not just for the ordinary aspects of science, but for all of life. I should think people would want to know that what they know is truly what the universe is like, or at least as close as they can get to it.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "The Law of conservation of energy tells us we can't get something for nothing, but we refuse to believe it.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "All mankind, right down to those you most despise, are your neighbors.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "We are meant to know, or we are amoebae. Suppose that we are wise enough to learn and know — and yet not wise enough to control our learning and knowledge, so that we use it to destroy ourselves? Even if that is so, knowledge remains better than ignorance. It is better to know — even if the knowledge endured only for the moment that comes before destruction — than to gain eternal life at the price of a dull and swinish lack of comprehension of a universe that swirls unseen before us in all its wonder.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I made up my mind long ago to follow one cardinal rule in all my writing — to be 'clear'. I have given up all thought of writing poetically or symbolically or experimentally, or in any of the other modes that might (if I were good enough) get me a Pulitzer prize. I would write merely clearly and in this way establish a warm relationship between myself and my readers, and the professional critics — Well, they can do whatever they wish.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "[Writing] is an addiction more powerful than alcohol, than nicotine, than crack. I could not conceive of not writing.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "Books ... hold within them the gathered wisdom of humanity, the collected knowledge of the world's thinkers, the amusement and excitement built up by the imaginations of brilliant people. Books contain humor, beauty, wit, emotion, thought, and, indeed, all of life. Life without books is empty.", Author = "Isaac Asimov" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "If anyone can be considered the greatest writer who ever lived, it is Shakespeare.", Author = "Isaac Asimov" },
        };
    }
